// The admin SPA and migrations embedded in the single binary. The entry point generated by
// scripts/build-cli.ts puts them on globalThis before startup. Absent when run as bun cli/main.ts
// (app/dist and migrations are read from disk)

import type { Migration } from '../src/backend/bun'

export interface Embedded {
  // URL path (e.g. /sites/index.html) -> path of the file inside the binary
  assets: Map<string, string>
  migrations: Migration[]
}

const KEY = '__dropEmbedded'

export function embedded(): Embedded | null {
  return ((globalThis as Record<string, unknown>)[KEY] as Embedded | undefined) ?? null
}
